 ctx.restore();ctx.lineJoin='round';ctx.lineCap='round';const path=offset=>{ctx.beginPath();ctx.moveTo(left-cam,surface(left)+offset);for(let x=left+6;x<right;x+=6)ctx.lineTo(x-cam,surface(x)+offset);ctx.lineTo(right-cam,surface(right)+offset);};path(5);ctx.strokeStyle='#425c39';ctx.lineWidth=14;ctx.stroke();path(1);ctx.strokeStyle='#80ab54';ctx.lineWidth=7;ctx.stroke();path(-2);ctx.strokeStyle='#c7d99a';ctx.lineWidth=2;ctx.stroke();ctx.lineCap='butt';
