function nearbySiren(){if(d.mode!=='platform'||!s.ground)return null;for(const [index,at] of [[13,.75],[27,.5]]){const p=s.platforms[index];if(p&&!p.gone&&Math.abs(s.x-(p.x+p.w*at))<65&&Math.abs(s.y-p.y)<12)return {index,x:p.x+p.w*at,y:p.y,siren:true};}return null;}
