function answerBooth(answer){if(!boothSession||![0,1,2].includes(answer))return;const replies=boothSession.index===16?[['Покерфейс повышенной опасности','«С таким счастливым лицом только кредиты одобрять. Запишем: радость скрытая.»'],['Побег из текущей раздачи','«Мысленно можно. Фишки оставьте здесь — они проходят по делу.»'],['Семь-два без разрешения','«Опять они! Эти двое уже обчистили половину нашего патруля.»']]:[['Тяжёлый миссклик','«Чек размером в три банка? У вас мышка с турбиной?»'],['Блеф первой категории','«Лицензия просрочена. Но покерфейс у вас убедительный.»'],['Ривер объявлен в розыск','«Пятый за смену! Ривер опять скрылся с места раздачи.»']];const first=!boothVisits.has(boothSession.index);boothVisits.add(boothSession.index);boothSession.shield=first;dialog.innerHTML='<h2>Протокол: '+replies[answer][0]+'</h2><p>'+replies[answer][1]+'</p><button data-booth-leave>Я больше не буду. Наверное.</button>';dialog.querySelector('button').focus({preventScroll:true});}
